contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 diff, uint256 limit, uint256 wagerAmount) public payable {
        require(address(this).balance >= wagerAmount, "not enough balance for wager");

        c.OpenToThePublic();
        c.AdjustDifficulty(diff);
        c.AdjustBetAmounts(limit);

        uint256 beforeWagerBal = address(this).balance;
        c.wager{value: wagerAmount}();

        require(wagerAmount == c.currentBetLimit(), "wager must equal bet limit");
        require(c.hasPlayerWagered(address(this)), "this must now be a player");

        uint256 cBalBeforePlay = address(c).balance;
        uint256 expectedPayout = cBalBeforePlay / 2;

        c.play();

        assert(
            !c.hasPlayerWagered(address(this)) &&
            address(c).balance == cBalBeforePlay - expectedPayout &&
            address(this).balance == beforeWagerBal - wagerAmount + expectedPayout
        );
    }
}

