contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, bool shouldOpen) public {
        require(caller != address(0), "caller must not be zero");
        if (!shouldOpen) {
            // If we don't open, the state should remain as it was: initially false.
            // Also attempt to call OpenToThePublic from a non-owner should revert.
            bool openBefore = true;
            (bool ok1, bytes memory data1) = address(c).call(abi.encodeWithSignature("openToPublic()"));
            require(ok1, "openToPublic getter failed");
            openBefore = abi.decode(data1, (bool));
            require(openBefore == false, "initial openToPublic should be false");

            bool reverted;
            try c.OpenToThePublic() {
                reverted = false;
            } catch {
                reverted = true;
            }
            bool openAfter = true;
            (bool ok2, bytes memory data2) = address(c).call(abi.encodeWithSignature("openToPublic()"));
            require(ok2, "openToPublic getter failed");
            openAfter = abi.decode(data2, (bool));
            assert(openAfter == false && openBefore == false);
        } else {
            // Owner calls OpenToThePublic; it should succeed and set openToPublic to true.
            bool openBefore = true;
            (bool ok1, bytes memory data1) = address(c).call(abi.encodeWithSignature("openToPublic()"));
            require(ok1, "openToPublic getter failed");
            openBefore = abi.decode(data1, (bool));
            require(openBefore == false, "initial openToPublic should be false");

            bool reverted;
            try c.OpenToThePublic() {
                reverted = false;
            } catch {
                reverted = true;
            }
            bool openAfter = false;
            (bool ok2, bytes memory data2) = address(c).call(abi.encodeWithSignature("openToPublic()"));
            require(ok2, "openToPublic getter failed");
            openAfter = abi.decode(data2, (bool));
            assert(reverted == false && openAfter == true);
        }
    }

    receive() external payable {}
}

